#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/util.h>

#define SLAB_BLOCK_SIZE 64
#define SLAB_NUM_BLOCKS 4

// Slab with 4-byte alignment
K_MEM_SLAB_DEFINE(test_slab_4_align, SLAB_BLOCK_SIZE, SLAB_NUM_BLOCKS, 4);

// Slab with 32-byte alignment
K_MEM_SLAB_DEFINE(test_slab_32_align, SLAB_BLOCK_SIZE, SLAB_NUM_BLOCKS, 32);

// Slab with 64-byte alignment (block size alignment)
K_MEM_SLAB_DEFINE(test_slab_64_align, SLAB_BLOCK_SIZE, SLAB_NUM_BLOCKS, 64);

/**
 * @brief Test memory slab allocation with various alignments.
 *
 * This test verifies that k_mem_slab_alloc returns pointers that are
 * correctly aligned according to the slab's definition. It also includes
 * a scenario for custom higher alignment within a block, ensuring the
 * original allocated pointer is freed to prevent slab corruption.
 */
void test_mslab_alloc_align(void)
{
    void *block_ptr;
    int ret;

    // Test with 4-byte aligned slab
    ret = k_mem_slab_alloc(&test_slab_4_align, &block_ptr, K_NO_WAIT);
    zassert_equal(ret, 0, "Allocation from 4-byte aligned slab failed");
    zassert_not_null(block_ptr, "Allocated block from 4-byte aligned slab is NULL");
    zassert_equal(((uintptr_t)block_ptr % 4), 0,
                  "Block from 4-byte aligned slab not 4-byte aligned");
    k_mem_slab_free(&test_slab_4_align, block_ptr);

    // Test with 32-byte aligned slab
    ret = k_mem_slab_alloc(&test_slab_32_align, &block_ptr, K_NO_WAIT);
    zassert_equal(ret, 0, "Allocation from 32-byte aligned slab failed");
    zassert_not_null(block_ptr, "Allocated block from 32-byte aligned slab is NULL");
    zassert_equal(((uintptr_t)block_ptr % 32), 0,
                  "Block from 32-byte aligned slab not 32-byte aligned");
    k_mem_slab_free(&test_slab_32_align, block_ptr);

    // Test with 64-byte aligned slab (block size alignment)
    ret = k_mem_slab_alloc(&test_slab_64_align, &block_ptr, K_NO_WAIT);
    zassert_equal(ret, 0, "Allocation from 64-byte aligned slab failed");
    zassert_not_null(block_ptr, "Allocated block from 64-byte aligned slab is NULL");
    zassert_equal(((uintptr_t)block_ptr % 64), 0,
                  "Block from 64-byte aligned slab not 64-byte aligned");
    k_mem_slab_free(&test_slab_64_align, block_ptr);

    // --- Custom higher alignment within a block scenario ---
    // This section demonstrates how to correctly handle a scenario where
    // a higher alignment than the slab's default is required for a sub-region
    // within an allocated block. The key is to always free the original pointer.

    void *original_block_ptr;
    void *aligned_sub_ptr;
    size_t required_alignment = 16; // Desired alignment for sub-pointer
    size_t required_data_size = 16; // Size of the data to be stored at aligned_sub_ptr

    // To guarantee finding a 16-byte aligned address within a 4-byte aligned block,
    // we might need to allocate a slightly larger block than just required_data_size.
    // The slab block size is 64, which is sufficient.
    // We need to ensure that (original_block_ptr + padding + required_data_size) fits within SLAB_BLOCK_SIZE.
    // The maximum padding needed for 16-byte alignment from a 4-byte aligned start is 12 bytes.
    // So, if SLAB_BLOCK_SIZE is 64, and we need 16 bytes of data, 64 >= (16 + 12) is true.

    ret = k_mem_slab_alloc(&test_slab_4_align, &original_block_ptr, K_NO_WAIT);
    zassert_equal(ret, 0, "Custom aligned allocation (original) failed");
    zassert_not_null(original_block_ptr, "Custom aligned original block is NULL");

    // Calculate the 16-byte aligned address within the allocated block.
    // This is the pointer the user would actually use.
    aligned_sub_ptr = (void *)ROUND_UP((uintptr_t)original_block_ptr, required_alignment);

    // Verify the sub-pointer is correctly aligned.
    zassert_equal(((uintptr_t)aligned_sub_ptr % required_alignment), 0,
                  "Custom aligned sub-pointer not %zu-byte aligned", required_alignment);

    // Verify that the aligned_sub_ptr is within the bounds of the original block.
    zassert_true((uintptr_t)aligned_sub_ptr >= (uintptr_t)original_block_ptr,
                 "Aligned sub-pointer is before original block start");
    zassert_true((uintptr_t)aligned_sub_ptr + required_data_size <= (uintptr_t)original_block_ptr + SLAB_BLOCK_SIZE,
                 "Aligned sub-pointer + data size exceeds original block bounds");

    // THE FIX: Always free the original pointer returned by k_mem_slab_alloc.
    // If the original test was freeing 'aligned_sub_ptr' here, that would cause corruption.
    k_mem_slab_free(&test_slab_4_align, original_block_ptr);
}

ZTEST_SUITE(mslab_api, NULL, NULL, NULL, NULL, NULL);

ZTEST(mslab_api, test_mslab_alloc_align)
{
    test_mslab_alloc_align();
}
